#include "charge.h"
#include "screen_staging.h"
#include "pose.h"
#include "../flow/phase_controller.h"
#include <algorithm>
namespace speed {
namespace {
void lock(RunRuntime &r,TechniqueState &t) {auto &v=std::get<DracoTechniqueState>(t.detail);auto &s=std::get<DracoChargeState>(v.move);const auto &b=*PhaseController::find(r,t.actor);const auto &p=r.content->boss_techniques[t.definition-1];const auto &d=*std::find_if(r.content->draco_charges.begin(),r.content->draco_charges.end(),[&](const auto &d){return d.technique==t.definition;});const double remaining=std::max(0.0,p.warn-v.stage_time),offset=105*b.draco.head_scale;auto predicted=r.state.ship_pos;for (int j=0;j<3;++j) {const double distance=s.origin.distance_to(predicted);const double fraction=std::clamp((distance-offset)/std::max(1.0,distance+d.overshoot),0.0,1.0);predicted=DracoTechnique::predict(r,t.actor,remaining+p.active*fraction,d.lead_cap);}t.aim=predicted;t.direction=(t.aim-s.origin).normalized();if (t.direction.is_zero_approx()) t.direction={1,0};r.state.enemies[t.actor.slot].facing=t.direction.angle();s.destination=t.aim+t.direction*d.overshoot;v.warning={s.origin+t.direction*offset,s.destination+t.direction*offset};v.warning_width=p.width;}
}
void DracoCharge::begin(RunRuntime &r,TechniqueState &t) {auto &v=std::get<DracoTechniqueState>(t.detail);v.move=DracoChargeState{};DracoScreenStaging::begin(r,t,std::get<DracoChargeState>(v.move).staging);t.locked=false;}
void DracoCharge::windup(RunRuntime &r,TechniqueState &t,double dt) {auto &v=std::get<DracoTechniqueState>(t.detail);auto &s=std::get<DracoChargeState>(v.move);if (!DracoScreenStaging::advance(r,t,s.staging,dt)) return;if (!s.positioned) {s.origin=r.state.enemies[t.actor.slot].pos;s.positioned=true;lock(r,t);}if (!t.locked) {lock(r,t);t.locked=v.stage_time>=std::min(0.2,r.content->boss_techniques[t.definition-1].warn*0.3);}}
void DracoCharge::active(RunRuntime &r,TechniqueState &t) {auto &v=std::get<DracoTechniqueState>(t.detail);const auto &s=std::get<DracoChargeState>(v.move);const auto &b=*PhaseController::find(r,t.actor);v.warning.clear();const auto before=DracoTechnique::mouth(r,b);r.state.enemies[t.actor.slot].pos=s.origin.lerp(s.destination,std::clamp(v.stage_time/r.content->boss_techniques[t.definition-1].active,0.0,1.0));const auto after=DracoTechnique::mouth(r,b);DracoTechnique::hit_segment(r,t,before,after,r.content->boss_techniques[t.definition-1].width,Cause::Charge);v.attack={before,after};}
void DracoCharge::end(RunRuntime &r,TechniqueState &t,bool cancelled) {auto &v=std::get<DracoTechniqueState>(t.detail);v.warning.clear();v.attack.clear();if (r.state.enemy_handles.contains(t.actor)) std::get<DracoChargeState>(v.move).settled=r.state.enemies[t.actor.slot].pos;if (cancelled) if (auto *b=PhaseController::find(r,t.actor)) DracoPose::reset(r,*b);}
void DracoCharge::recover(RunRuntime &r,TechniqueState &t) {const auto &v=std::get<DracoTechniqueState>(t.detail);const auto &s=std::get<DracoChargeState>(v.move);r.state.enemies[t.actor.slot].pos=s.settled+t.direction*45*DracoTechnique::smooth(v.stage_time/std::max(0.001,r.content->boss_techniques[t.definition-1].recover));}
bool DracoCharge::validate(const DracoChargeState &s) {return s.origin.is_finite() && s.destination.is_finite() && s.settled.is_finite() && DracoScreenStaging::validate(s.staging);}
godot::Dictionary DracoCharge::snapshot(const TechniqueState &t) {const auto &s=std::get<DracoChargeState>(std::get<DracoTechniqueState>(t.detail).move);godot::Dictionary out;out["staging_ready"]=s.staging.phase==2;out["exit_time"]=s.staging.exit_time;out["staging_side"]=s.staging.side;out["origin"]=s.origin;out["destination"]=s.destination;return out;}
}
